{
  "steps": [
    {
      "action": "Inventory the target binary and analysis prerequisites: record hash, format, architecture, entrypoints, sections, imports, exports, symbols, strings, protections, and analysis blockers before deeper validation recovery.",
      "technique": "RE-BINARY-INVENTORY",
      "deterministic_check": [
        "The analyzed artifact hash matches campaign metadata.",
        "Binary format and architecture are recorded.",
        "Expected inventory artifacts exist and parse successfully.",
        "Missing or malformed inputs are reported as incomplete rather than absence."
      ]
    },
    {
      "action": "Map static call relationships around the input surface, including entrypoints, callers, callees, virtualized dispatch candidates, and data-flow-relevant helpers leading to validation logic.",
      "technique": "RE-STATIC-CALLGRAPH",
      "deterministic_check": [
        "Every claimed call edge has an address or symbol locator.",
        "Unresolved indirect calls are listed explicitly.",
        "The call graph identifies which paths are proven and which remain candidates."
      ]
    },
    {
      "action": "Trace input acquisition through virtualized parsing, transformations, comparisons, branch decisions, success paths, and rejection paths; derive the accepted-input constraints and compute a candidate input that satisfies the success path.",
      "technique": "RE-INPUT-VALIDATION-TRACE",
      "deterministic_check": [
        "The input source and destination representation are identified.",
        "Every success and rejection branch has a code locator.",
        "Transformations and comparison constants are supported by decompilation or disassembly evidence.",
        "Unknown helper behavior is represented as an unresolved dependency.",
        "The computed candidate input satisfies all recorded success-branch constraints and avoids all recorded rejection-branch constraints."
      ]
    },
    {
      "action": "Confirm the candidate input with a bounded network-isolated local replay using an authorized debugger or instrumentation probe; set readiness sensors, trigger the input, bound the timeout, and verify the validation success path is hit.",
      "technique": "RE-BOUNDED-RUNTIME-CONFIRMATION",
      "deterministic_check": [
        "Runtime execution is authorized by campaign scope.",
        "Network isolation is verified before the replay trigger is issued.",
        "The sensor or breakpoint is proven ready before interpreting hits or zero hits.",
        "The trigger window and timeout are bounded and recorded.",
        "Runtime identity is correlated to the same binary hash and module as static evidence.",
        "The validation success path is hit within the bounded window and no rejection path is hit.",
        "No network egress is observed during the replay."
      ]
    }
  ]
}
